import { useState, useEffect } from "react";
import axios from "axios";
import { useLocation, useNavigate } from "react-router-dom";

function UserDetails() {
  const { state } = useLocation();
  const navigate = useNavigate();
  const { houseId, selectedDates, startDate, days, amount } = state || {};
  const [userDetails, setUserDetails] = useState({
    name: "",
    phone: "",
    email: "",
    idProof: "",
  });
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!houseId || !startDate || !days || !amount) {
      setError("Missing booking details. Please try again.");
      setTimeout(() => navigate("/homes"), 3000);
    }
  }, [houseId, startDate, days, amount, navigate]);

  const handleUserSubmit = async (e) => {
    e.preventDefault();
    if (
      !userDetails.name ||
      !userDetails.phone ||
      !userDetails.email ||
      !userDetails.idProof
    ) {
      setError("Please fill in all fields.");
      return;
    }

    try {
      const userId = localStorage.getItem("userId");
      if (!userId) {
        setError("User ID not found. Please log in.");
        return;
      }
      const response = await axios.post("http://localhost:5000/api/send-otp", {
        phone: userDetails.phone,
        email: userDetails.email,
        userId,
      });
      if (response.data.success) {
        setOtpSent(true);
        setError("OTP sent to your phone and email. Please enter it below.");
      } else {
        setError(response.data.error || "Failed to send OTP.");
      }
    } catch (error) {
      console.error("Error sending OTP:", error);
      setError("Failed to send OTP. Please try again.");
    }
  };

  const handleOtpVerify = async () => {
    try {
      const userId = localStorage.getItem("userId");
      const response = await axios.post(
        "http://localhost:5000/api/verify-otp",
        {
          phone: userDetails.phone,
          userId,
          otp,
        }
      );

      if (response.data.success) {
        const orderResponse = await axios.post(
          "http://localhost:5000/api/order",
          {
            amount,
            houseId,
            userId,
            userDetails,
            start_date: startDate,
            days,
          }
        );
        const {
          orderId,
          amount: orderAmount,
          currency,
          bookingId,
        } = orderResponse.data;

        const options = {
          key: process.env.REACT_APP_RAZORPAY_KEY_ID,
          amount: orderAmount,
          currency,
          name: "Nest Finder",
          description: `Booking for House ${houseId}`,
          order_id: orderId,
          handler: async (response) => {
            try {
              await axios.post("http://localhost:5000/api/payment/verify", {
                razorpay_order_id: response.razorpay_order_id,
                razorpay_payment_id: response.razorpay_payment_id,
                razorpay_signature: response.razorpay_signature,
                houseId,
                userId,
                amount,
                bookingId,
                startDate,
                days,
              });
              navigate(`/booking-confirmation/${bookingId}`, {
                state: { refresh: true },
              });
            } catch (error) {
              console.error("Payment verification failed:", error);
              setError("Payment verification failed. Please try again.");
            }
          },
          prefill: {
            name: userDetails.name,
            email: userDetails.email,
            contact: userDetails.phone,
          },
          theme: { color: "#3399cc" },
          modal: {
            ondismiss: () => {
              setError("Payment was cancelled or failed to complete.");
            },
          },
        };

        const rzp = new window.Razorpay(options);
        rzp.open();
      } else {
        setError(response.data.error || "Invalid OTP.");
      }
    } catch (error) {
      console.error("Error verifying OTP:", error);
      setError("Failed to verify OTP. Please try again.");
    }
  };

  return (
    <div
      style={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: "#f0f0f0",
      }}
    >
      <div
        style={{
          backgroundColor: "white",
          padding: "2rem",
          borderRadius: "0.5rem",
          boxShadow: "0 4px 6px rgba(0, 0, 0, 0.1)",
          width: "400px",
          textAlign: "center",
        }}
      >
        <h4 style={{ fontSize: "1.5rem", marginBottom: "1rem" }}>
          Enter User Details
        </h4>
        {!otpSent ? (
          <form onSubmit={handleUserSubmit}>
            <input
              type="text"
              placeholder="Name"
              value={userDetails.name}
              onChange={(e) =>
                setUserDetails({ ...userDetails, name: e.target.value })
              }
              style={{ width: "80%", padding: "0.5rem", marginBottom: "1rem" }}
            />
            <input
              type="tel"
              placeholder="Phone (e.g., +918778086452)"
              value={userDetails.phone}
              onChange={(e) =>
                setUserDetails({ ...userDetails, phone: e.target.value })
              }
              style={{ width: "80%", padding: "0.5rem", marginBottom: "1rem" }}
            />
            <input
              type="email"
              placeholder="Email"
              value={userDetails.email}
              onChange={(e) =>
                setUserDetails({ ...userDetails, email: e.target.value })
              }
              style={{ width: "80%", padding: "0.5rem", marginBottom: "1rem" }}
            />
            <input
              type="text"
              placeholder="ID Proof (e.g., Aadhaar number)"
              value={userDetails.idProof}
              onChange={(e) =>
                setUserDetails({ ...userDetails, idProof: e.target.value })
              }
              style={{ width: "80%", padding: "0.5rem", marginBottom: "1rem" }}
            />
            <button
              type="submit"
              style={{
                padding: "0.5rem 1rem",
                backgroundColor: "#4CAF50",
                color: "white",
                borderRadius: "0.3rem",
              }}
            >
              Send OTP
            </button>
          </form>
        ) : (
          <div>
            <input
              type="text"
              placeholder="Enter OTP"
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              style={{ width: "80%", padding: "0.5rem", marginTop: "1rem" }}
            />
            <button
              onClick={handleOtpVerify}
              style={{
                padding: "0.5rem 1rem",
                backgroundColor: "#2196F3",
                color: "white",
                borderRadius: "0.3rem",
                marginTop: "1rem",
              }}
            >
              Verify OTP
            </button>
          </div>
        )}
        {error && (
          <p
            style={{
              color: error.includes("OTP sent") ? "green" : "red",
              marginTop: "1rem",
            }}
          >
            {error}
          </p>
        )}
        <button
          onClick={() => navigate(-1)}
          style={{
            marginTop: "1rem",
            padding: "0.5rem 1rem",
            backgroundColor: "#ef4444",
            color: "white",
            borderRadius: "0.3rem",
          }}
        >
          Cancel
        </button>
      </div>
    </div>
  );
}

export default UserDetails;
